var STOP={'的':1,'了':1,'和':1,'是':1,'在':1,'我':1,'你':1,'他':1,'她':1,'我们':1,
'the':1,'a':1,'an':1,'and':1,'of':1,'to':1,'in':1,'is':1,'it':1,'for':1,'on':1,'with':1,'this':1,'that':1};
function freq(text, topN, removeStop){
  var tokens=text.toLowerCase().match(/[a-z0-9\u4e00-\u9fa5]+/g)||[];
  var map={};
  for(var i=0;i<tokens.length;i++){ var t=tokens[i]; if(removeStop && STOP[t]) continue; map[t]=(map[t]||0)+1; }
  var arr=Object.keys(map).map(function(k){return [k,map[k]];});
  arr.sort(function(a,b){ return b[1]-a[1] || (a[0]<b[0]?-1:1); });
  if(topN) arr=arr.slice(0,topN);
  return arr;
}
var EXPORTS={freq:freq, STOP:STOP};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.WordFrequencyForgePure = EXPORTS; }
